// Single source of truth for the magnet appearance/definition contract's
// enumerable vocab (display modes, theme modes, auto-open triggers, hub CTA
// action types) and the web-font allowlist. Previously three independently
// maintained copies that happened to agree — apps/service-api/src/routes/
// magnets.js's DISPLAY_MODES/THEME_MODES/TRIGGERS/ACTION_TYPES/ROUTE_KEYS,
// apps/client-saas/src/routes/magnets-route.js's DISPLAY_OPTS/THEME_OPTS/
// TRIGGER_OPTS/CTA_META, and shared/machfivemagnet.js's scattered inline
// literal checks in setupTrigger()/the CTA-type dispatch — the same drift
// shape stepTypes.js/leadCaptureFields.js closed off for step types and lead
// fields, deliberately deferred here until one of the three files was touched
// again anyway (see design/docs — this session's own passkey/GA4/templates
// work finally touched machfivemagnet.js repeatedly).
//
// shared/machfivemagnet.js is the one consumer that CANNOT import this
// module: it's a self-contained IIFE shipped raw as a <script> tag on
// arbitrary customer sites (only ever passed through terser, a minifier —
// no bundler, no module resolution at that point). Its hardcoded copies are
// cross-checked against this file by a permanent test instead
// (magnet-vocab-sdk-consistency.test.js in apps/client-saas), so a future
// drift there still fails loudly instead of silently — see that test's own
// header comment for exactly what it can and can't catch.

// Canonical order matches the client-saas configurator's presentation order
// (DISPLAY_OPTS/THEME_OPTS/TRIGGER_OPTS) where the two already agreed, so
// deriving the UI's option order directly from this array (same pattern
// magnet-flow.js already uses for STEP_TYPES/TYPE_ORDER) changes nothing
// about what a user sees.
export const DISPLAY_MODES = [
  { value: 'inline', label: 'Inline' },
  { value: 'chat', label: 'Chat' },
  { value: 'right_slide', label: 'Slide' },
  { value: 'modal', label: 'Modal' },
];
export const THEME_MODES = [
  // 'auto' follows the VISITOR'S OS via prefers-color-scheme. 'sync' follows the HOST
  // SITE's own theme — many sites let a visitor pick a theme independent of their OS,
  // and CSS inside a shadow root cannot see that choice, so the SDK reads <html>
  // directly (data-theme/data-mode/data-color-scheme, then color-scheme, then a
  // dark/theme-dark class) and mirrors it. A site using none of those conventions
  // degrades to the 'auto' behaviour, so 'sync' is never worse than 'auto'.
  { value: 'auto', label: 'Auto (visitor OS setting)' },
  { value: 'sync', label: "Sync (match the site's own dark mode)" },
  { value: 'light', label: 'Light' },
  { value: 'dark', label: 'Dark' },
];
// Auto-open triggers the SDK honors; 'none' (or any unknown value) means manual open only.
export const TRIGGERS = [
  { value: 'on_load', label: 'Immediately on page load' },
  { value: 'on_8_seconds', label: 'After 8 seconds' },
  { value: 'on_scroll_80_percent', label: 'At 80% scroll depth' },
  { value: 'on_exit_intent', label: 'On exit intent (mouse leaves the page)' },
  { value: 'none', label: 'Manual only (visitor clicks the launcher)' },
];
// Hub CTA types: call/email reveal a contact, book runs the in-panel scheduler
// (or a booking link), chat runs the guided flow, support runs a multi-select
// intake. Only call/email require a value (VALUE_REQUIRED_ACTION_TYPES).
// Order here is the backend's original validation-array order, NOT a UI
// presentation order — client-saas's own CTA_ORDER is a deliberately
// different curated display order (book/chat/call/email/support) and stays
// its own hand-authored constant; only the value SET is cross-checked.
export const ACTION_TYPES = [
  { value: 'book', label: 'Book' },
  { value: 'call', label: 'Call' },
  { value: 'email', label: 'Email' },
  { value: 'chat', label: 'Chat' },
  { value: 'support', label: 'Support' },
];
export const VALUE_REQUIRED_ACTION_TYPES = ['call', 'email'];
// Flow routes a step array can target: the default chat flow (mag_macro_steps) or a CTA route.
export const ROUTE_KEYS = ['chat', 'book', 'support'];

export const DISPLAY_MODE_VALUES = DISPLAY_MODES.map((m) => m.value);
export const THEME_MODE_VALUES = THEME_MODES.map((m) => m.value);
export const TRIGGER_VALUES = TRIGGERS.map((t) => t.value);

/**
 * 'manual' is an accepted INPUT alias for 'none', not a second canonical token.
 *
 * 'none' already means "Manual only (visitor clicks the launcher)". The device-aware
 * form reads far better as { desktop: 'on_load', mobile: 'manual' } than with 'none',
 * so the word is accepted and folded to the existing value. Adding it to TRIGGERS
 * instead would leave two tokens meaning one thing, and every consumer would have to
 * know both — the duplication this codebase keeps having to unpick.
 */
export const TRIGGER_ALIASES = Object.freeze({ manual: 'none' });

/** A single token → its canonical form, or null if it is not a trigger we honour. */
export function normalizeTriggerToken(value) {
  if (typeof value !== 'string') return null;
  const v = TRIGGER_ALIASES[value.trim()] || value.trim();
  return TRIGGER_VALUES.includes(v) ? v : null;
}

/**
 * Accepts EITHER the historical single string or the device-aware object, and returns
 * the canonical form — or null if nothing usable is in there.
 *
 *   'on_load'                                  -> 'on_load'
 *   { desktop: 'on_load', mobile: 'manual' }   -> { desktop: 'on_load', mobile: 'none' }
 *   { mobile: 'manual' }                       -> { desktop: 'none', mobile: 'none' }
 *
 * A missing side becomes 'none' rather than inheriting the other: a half-specified
 * object most likely means "only this device should auto-open", and defaulting the
 * unspecified side to auto-open would be the surprising reading of that.
 *
 * Shared so the API's validation and the SDK's runtime resolution cannot drift — the
 * SDK ships standalone and cannot import this, so its copy is pinned by a differential
 * test instead (see the SDK trigger tests).
 */
export function normalizeTrigger(value) {
  if (typeof value === 'string') return normalizeTriggerToken(value);
  if (value && typeof value === 'object' && !Array.isArray(value)) {
    const desktop = normalizeTriggerToken(value.desktop);
    const mobile = normalizeTriggerToken(value.mobile);
    if (desktop === null && mobile === null) return null;
    return { desktop: desktop || 'none', mobile: mobile || 'none' };
  }
  return null;
}
export const ACTION_TYPE_VALUES = ACTION_TYPES.map((a) => a.value);

// Web fonts the builder offers and the SDK's ensureWebFont() will actually load
// (via Google Fonts CSS2) — system/web-safe fonts aren't listed since they
// already render everywhere with no network fetch needed. `key` is the
// lowercased first-family match ensureWebFont() looks up by; `googleSpec` is
// the exact CSS2 family query string; `fallback` drives both the CSS stack's
// generic family and whether the picker labels it "(serif)".
