// Splash is the ONLY unauth landing mvvLegit allows in every auth state (incl. the
// brand-new state 0 of a cold incognito load), so it's where invite links,
// questionnaire fill-out links and deliverable review links are funneled. All
// three ride real query-string params (?uid=&token= / ?qr=&token= / ?dl=&token=),
// which survive the bounce — render the matching form when present.
const loadSplash = () => {
  console.log('[Router] Route: splash');
  PubSub.publish(AppBroadcast.ROUTE_NAV_BEFORE, { route: 'splash' });
  // WHICH public landing this is (if any) comes from core/publicLanding.js — the same
  // module AuthController's nav guard consults to decide whether to suppress mvvLegit's
  // redirect to signin. Two independent copies of that condition is how the guard went
  // dead twice; see that file's header.
  const landing = publicLandingFor()?.name;
  // Use LITERAL import() strings in each branch — a computed import(variable) is not
  // statically analyzable by Vite, so the chunk is never emitted/deployed (→ 404 at
  // runtime). That is also why the module path is not stored in the registry next to
  // the name; a test keeps the two in step instead.
  const loader = landing === 'invite'
    ? import('./routes/accept-invite-route.js')
    : landing === 'questionnaire'
      ? import('./routes/questionnaire-fill-route.js')
      : landing === 'deliverable'
        ? import('./routes/deliverable-fill-route.js')
        : import('./routes/splash-route.js');
  loader
    .then(module => {
      const container = document.getElementById('app');
      container.innerHTML = module.render();
      if (module.init) module.init();
      PubSub.publish(AppBroadcast.ROUTE_NAV_AFTER, { route: 'splash' });
    })
    .catch(err => {
      console.error('[Router] Error loading splash route:', err);
      PubSub.publish(AppBroadcast.ROUTE_NAV_ERROR, { route: 'splash', error: err });
    });
};
router.on('/', loadSplash);
router.on('/splash', loadSplash);

