/**
 * listExpand.js — one implementation of "show the first N rows, with a way to see the rest".
 *
 * Every list view in the app grew its own answer to this, or none at all: leads capped at
 * 100 behind a bespoke "Show N more" button, most others rendered the entire collection,
 * and a few silently sliced to a fixed count with no way to reach what was hidden. So the
 * same report ("this list is enormous" / "I can't see the rest") arrived once per page,
 * and each fix landed in one route's private ensureStyles().
 *
 * This is deliberately NOT a list component. The routes render wildly different markup —
 * tables, cards, rows, pending-invite strips — and rewriting them all around one renderer
 * would be a far bigger change than the problem justifies. It is the smallest shared
 * thing that removes the duplication: decide how many rows to show, and render the
 * control that reveals the rest.
 *
 * WHY A CAP AND NOT PAGINATION. The cap is about the page being readable and cheap to
 * render, not about how much data was fetched. Server-side paging (see the leads list's
 * `limit`/`total`) is a separate concern and stays where it is; this only governs how many
 * of the rows a route ALREADY HAS get put into the DOM at once.
 *
 * NOT FOR: anything already virtualised, or a list whose whole point is completeness in
 * one view (an export preview, a print sheet).
 */

/**
 * Rows shown before the expand control appears — the app-wide standard.
 *
 * One number, everywhere, with no page-specific exceptions: the moment lists are allowed
 * their own caps, "how much of this list do I see" stops being a thing you learn once and
 * becomes a thing you rediscover per page. Raise it here and every list moves together.
 */
export const LIST_CAP = 25;

/** Rows revealed per expand click, and the step used by "Show N more". */
export const LIST_STEP = 25;

/**
 * How many rows to render right now.
 * @param {number} total - rows the route holds
 * @param {number} [shown] - rows currently revealed; defaults to the cap
 * @returns {number}
 */
export function visibleCount(total, shown = LIST_CAP) {
  const n = Number.isFinite(shown) && shown > 0 ? shown : LIST_CAP;
  return Math.min(n, Math.max(0, total));
}

/**
 * The expand control, or '' when everything is already on screen.
 *
 * Says how many more are coming AND how many remain, because "Show more" alone leaves the
 * reader unable to tell a list with three hidden rows from one with three hundred — which
 * is the thing that makes a capped list feel like a dead end rather than a summary.
 *
 * @param {object} opts
 * @param {number} opts.total - rows the route holds
 * @param {number} opts.shown - rows currently revealed
 * @param {string} [opts.id] - element id, when a route needs to target it directly
 * @param {string} [opts.noun] - plural noun for the label ("leads", "sites")
 * @param {number} [opts.step] - rows the next click reveals
 * @returns {string} HTML, or '' when there is nothing left to reveal
 */
export function expandButtonHTML({ total, shown, id = '', noun = '', step = LIST_STEP } = {}) {
  const remaining = Math.max(0, (total || 0) - (shown || 0));
  if (remaining <= 0) return '';
  const next = Math.min(step, remaining);
  const what = noun ? ` ${escapeAttr(noun)}` : '';
  return `<button type="button" class="m5t-list-more"${id ? ` id="${escapeAttr(id)}"` : ''}`
    + ` data-action="list-expand" data-remaining="${remaining}"`
    + ` aria-label="Show ${next} more${what}, ${remaining} remaining">`
    + `Show ${next} more${what} <span class="m5t-list-more__rest">(${remaining} remaining)</span>`
    + '</button>';
}

/**
 * Wire the control inside `root`. Calls `onExpand(nextShown)` with the new count; the
 * route re-renders however it already does.
 *
 * Returns a cleanup function — routes that re-render into the same container would
 * otherwise stack listeners on every repaint.
 *
 * @param {ParentNode} root
 * @param {object} opts
 * @param {number} opts.shown - rows currently revealed
 * @param {number} [opts.step]
 * @param {(nextShown: number) => void} opts.onExpand
 * @returns {() => void} cleanup
 */
export function wireExpand(root, { shown, step = LIST_STEP, onExpand } = {}) {
  const btn = root?.querySelector?.('[data-action="list-expand"]');
  if (!btn || typeof onExpand !== 'function') return () => {};
  const handler = () => onExpand((shown || LIST_CAP) + step);
  btn.addEventListener('click', handler);
  return () => btn.removeEventListener('click', handler);
}

/**
 * Cap an ALREADY-RENDERED list and wire its expand control, without touching how the
 * route renders.
 *
 * The slice-and-re-render form above needs a `shown` in route state and a re-render
 * function to call. Most routes have neither: they build one HTML string and assign it.
 * Asking each of them to grow paging state is how a shared fix turns into twenty
 * bespoke ones, so this variant does the whole job from the DOM — hide the overflow,
 * append the control, reveal a step per click.
 *
 * Trade-off, stated plainly: every row is still in the DOM, so this bounds what a reader
 * has to scan, not what the browser parses. That is the actual complaint ("this list is
 * enormous"), and where payload size is the problem the answer is server-side paging,
 * which is a different fix in a different layer.
 *
 * Idempotent: re-running on the same container clears its previous control and state, so
 * routes that re-render on every filter change can call it unconditionally.
 *
 * @param {ParentNode} container - element holding the rows
 * @param {object} opts
 * @param {string} opts.rowSelector - selects the repeating rows within `container`
 * @param {number} [opts.cap]
 * @param {number} [opts.step]
 * @param {string} [opts.noun]
 * @param {ParentNode} [opts.controlHost] - where the button goes; defaults to `container`
 * @returns {number} how many rows were hidden (0 when the list fits)
 */
export function capList(container, { rowSelector, cap = LIST_CAP, step = LIST_STEP, noun = '', controlHost } = {}) {
  if (!container || !rowSelector) return 0;
  container.querySelectorAll(':scope > .m5t-list-more, .m5t-list-more').forEach((b) => b.remove());

  const rows = [...container.querySelectorAll(rowSelector)];
  rows.forEach((r) => r.removeAttribute('hidden'));
  if (rows.length <= cap) return 0;

  let shown = cap;
  const host = controlHost || container;

  const paint = () => {
    rows.forEach((r, i) => {
      if (i < shown) r.removeAttribute('hidden');
      else r.setAttribute('hidden', '');
    });
    host.querySelectorAll('.m5t-list-more').forEach((b) => b.remove());
    const html = expandButtonHTML({ total: rows.length, shown, noun, step });
    if (!html) return;
    host.insertAdjacentHTML('beforeend', html);
    host.querySelector('.m5t-list-more')?.addEventListener('click', () => {
      shown += step;
      paint();
    });
  };

  paint();
  return rows.length - cap;
}

function escapeAttr(s) {
  return String(s ?? '').replace(/[&<>"']/g, (c) => (
    { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]
  ));
}
